// Node server example: use as async iterator and pipe into SSE
const hybrid = createHybridStream<string>(response);
for await (const chunk of hybrid.asAsyncIterator()) {
  sendSSE(chunk);
}
// Browser UI: same hybrid exposed to component as ReadableStream for streaming rendering
const readable = hybrid.asReadableStream();
const reader = readable.getReader();
while (true) {
  const {value, done} = await reader.read();
  if (done) break;
  renderChunk(value);
}
// Resume example: transient 502 after some tokens emitted
const token = hybrid.snapshotResumeToken();
// underlying HTTP transport fails -> SDK detects and attempts resume
const ok = await hybrid.resume(token);
if (!ok) {
  // fallback: re-run request and replay prefix cache
  await fallbackToFullRetry();
}
// Cancellation propagation: component unmount cancels both readers
hybrid.cancel('component-unmount');
